# Save as env_report.py and run with:  python env_report.py

installed = ["requests==2.31.0", "pandas==2.2.2", "rich==13.7.1"]
needed = ["requests", "pandas", "matplotlib"]


def read_requirements(lines):
    """Turn a list like ["name==version"] into a dictionary {name: version}."""
    versions = {}
    for line in lines:
        parts = line.split("==")
        name = parts[0]
        version = parts[1]
        versions[name] = version
    return versions


def report(versions, wanted):
    """Print one line per wanted package: its version, or that it is missing."""
    for name in wanted:
        if name in versions:
            print(name + " is installed, version " + versions[name])
        else:
            print(name + " is MISSING from this environment")


versions = read_requirements(installed)
report(versions, needed)

